INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mvu2tqgr-504925', '2026-10-29T21:49:54.363Z', 'Thomas Uriel Fernández', NULL, 'convencion', NULL, 'El proyecto se presenta como un desarrollo de COTO', 'Ningún archivo nuevo menciona la universidad, el trabajo práctico ni la materia. Textos, código y documentación se escriben como un producto interno de COTO.', 'CLAUDE.md', NULL, NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mvu2tqi9-67bd33', '2026-10-29T21:49:54.417Z', 'Thomas Uriel Fernández', NULL, 'convencion', NULL, 'Memoria compartida obligatoria', 'Toda IA del equipo lee ''contexto'' al empezar y registra decisiones, aprendizajes, pendientes y eventos al terminar. .claude/memoria/ va en el mismo commit que el cambio.', '.claude/memoria/README.md', NULL, NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mvu2tqjo-1852e1', '2026-10-29T21:49:54.468Z', 'Thomas Uriel Fernández', NULL, 'convencion', NULL, 'Flujo /equipo con cinco agentes', 'lider → disenador-ux-ui (si hay UI) → implementador → tester + reviewer + auditoría en paralelo → correcciones (máx. 3) → cierre del lider. Artefactos en .claude/work/<slug>/.', '.claude/skills/equipo/SKILL.md,docs/harness-engineering.md', NULL, NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mvu2tqkz-4f19e4', '2026-10-29T21:49:54.515Z', 'Thomas Uriel Fernández', 'disenador-ux-ui', 'decision', NULL, 'Tokens del Design System alineados a las Foundations de COTO', 'Se corrigieron 15 colores que diferían de las láminas. --info-900 pasó a --info-800. Se agregaron espaciado de 8 pt, grilla 1024/9 columnas, roles semánticos y components.css con los átomos.', 'frontend/src/styles/tokens.css,frontend/src/styles/components.css,docs/design-system/README.md', NULL, NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mvu2tqmc-64bcd0', '2026-10-29T21:49:54.565Z', 'Thomas Uriel Fernández', 'disenador-ux-ui', 'decision', NULL, 'Primary 700 = #A41908 (la lámina dice #041988)', '#041988 es azul y no coincide con la muestra roja. Se conserva #A41908 (contraste 7.72:1; la lámina indica 8.88). Confirmar con diseño.', 'frontend/src/styles/tokens.css', NULL, NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mvu2tqnn-2fa518', '2026-10-29T21:49:54.611Z', 'Thomas Uriel Fernández', 'disenador-ux-ui', 'decision', NULL, 'Botón Warning con texto oscuro', 'Texto blanco sobre #DDAD00 da 2:1 y no cumple AA. Se usa Neutral 900.', 'frontend/src/styles/components.css', NULL, NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mvu2tqp1-c500bd', '2026-10-29T21:49:54.661Z', 'Thomas Uriel Fernández', 'disenador-ux-ui', 'decision', NULL, 'Íconos con lucide-react en lugar de Untitled UI', 'Misma base Feather, outline y trazo redondeado; evita una dependencia nueva. Tamaños 24/32/48.', 'docs/design-system/README.md', NULL, NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mvu2tqqh-e1828c', '2026-10-29T21:49:54.713Z', 'Thomas Uriel Fernández', NULL, 'aprendizaje', NULL, 'components.css se importa antes de app.css', 'Las reglas de cada vista (anchos de botón en móvil, etc.) deben poder pisar a los átomos con la misma especificidad.', 'frontend/src/main.tsx', NULL, NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mvu2tqrx-592f71', '2026-10-29T21:49:54.765Z', 'Thomas Uriel Fernández', NULL, 'pendiente', NULL, 'Confirmar con diseño el hex de Primary 700', 'Ver decisión de Primary 700.', NULL, 'abierta', NULL);
