INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mvu2xkjh-9c7cbe', '2026-10-29T21:52:53.309Z', 'Thomas Uriel Fernández', NULL, 'decision', NULL, 'La historia del proyecto se expresa en versiones v0.1 a v0.4', 'Las antiguas etapas pasan a ser versiones del producto: v0.1 Dominio, v0.2 Aplicación y persistencia, v0.3 API REST, v0.4 Frontend. Coinciden con pom.xml y package.json. Los nombres de archivo (docs/etapa-*.md, upgrade-etapa2.sql, UpgradeEtapaDosTest) se conservan para no romper enlaces ni pruebas.', 'README.md,docs/etapa-1.md,docs/etapa-2.md,docs/etapa-3.md,docs/etapa-4.md', NULL, NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mvu2xkky-cf563d', '2026-10-29T21:52:53.362Z', 'Thomas Uriel Fernández', NULL, 'evento', NULL, 'Docs sin referencias académicas', NULL, 'docs/,README.md', NULL, NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mvu3aqpr-80a2c9', '2026-10-29T22:03:07.840Z', 'Thomas Uriel Fernández', NULL, 'pendiente', NULL, '[Alta] Autenticación y roles de sucursal', 'No hay Spring Security; el usuario de movimientos llega como texto en el body. Login con roles (Recepción, Repositor, Compras, Supervisor), usuario tomado del token y permisos por acción.', 'backend/pom.xml,backend/src/main/java/ar/com/coto/stock/dto/Solicitudes.java,backend/src/main/java/ar/com/coto/stock/config/', 'abierta', NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mvu3aqr7-eadc56', '2026-10-29T22:03:07.891Z', 'Thomas Uriel Fernández', NULL, 'pendiente', NULL, '[Alta] Frontend recarga todo cada 20 s y hace N+1 de políticas', 'store.tsx pide todo cada 20 s y una política por artículo simple. Crear GET /api/politicas, paginar /movimientos y /auditoria, y recargar solo lo afectado por cada operación.', 'frontend/src/store.tsx,frontend/src/api.ts,backend/src/main/java/ar/com/coto/stock/controller/MovimientoController.java,backend/src/main/java/ar/com/coto/stock/controller/ReposicionController.java', 'abierta', NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mvu3aqsn-446388', '2026-10-29T22:03:07.943Z', 'Thomas Uriel Fernández', NULL, 'pendiente', NULL, '[Media] Pruebas automatizadas de frontend', 'No hay suite. Vitest + Testing Library para store, formularios y modales; Playwright para 2-3 recorridos críticos (reservar, recibir pedido).', 'frontend/package.json,frontend/src/store.tsx', 'abierta', NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mvu3aqu2-f13c57', '2026-10-29T22:03:07.995Z', 'Thomas Uriel Fernández', NULL, 'pendiente', NULL, '[Media] Validar contra PostgreSQL real con Testcontainers', 'El perfil postgres nunca se ejecutó contra un servidor real; solo H2 en modo PostgreSQL.', 'backend/src/test/java/ar/com/coto/stock/persistence/,backend/src/main/resources/application-postgres.properties', 'abierta', NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mvu3aqvh-e1c662', '2026-10-29T22:03:08.045Z', 'Thomas Uriel Fernández', NULL, 'pendiente', NULL, '[Media] Migrar app.css y shell.css a tokens del Design System', 'Quedan ~40 colores sueltos, ~105 font-size en px y ~226 espaciados fuera de la grilla de 8. Auditoría del disenador-ux-ui y migración vista por vista.', 'frontend/src/styles/app.css,frontend/src/styles/shell.css', 'abierta', NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mvu3aqwv-0e2e09', '2026-10-29T22:03:08.095Z', 'Thomas Uriel Fernández', NULL, 'pendiente', NULL, '[Media] Documentar la API con OpenAPI/Swagger (springdoc)', '47 operaciones documentadas solo en markdown y Postman.', 'backend/pom.xml,backend/src/main/java/ar/com/coto/stock/controller/', 'abierta', NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mvu3aqy8-aa1095', '2026-10-29T22:03:08.144Z', 'Thomas Uriel Fernández', NULL, 'pendiente', NULL, '[Producto] Lotes y vencimientos con salida FEFO', 'Para lácteos, fiambres y carnes: lote, fecha de vencimiento, alerta de próximo a vencer y salida primero-vence-primero-sale.', NULL, 'abierta', NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mvu3aqzj-a34609', '2026-10-29T22:03:08.191Z', 'Thomas Uriel Fernández', NULL, 'pendiente', NULL, '[Producto] Mermas y roturas como movimiento propio', 'Tipo de movimiento con motivo obligatorio y reporte, separado de los ajustes.', NULL, 'abierta', NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mvu3ar0v-61c350', '2026-10-29T22:03:08.239Z', 'Thomas Uriel Fernández', NULL, 'pendiente', NULL, '[Producto] Inventario cíclico (conteo de góndola)', 'Contar, comparar contra el sistema y generar ajuste aprobado por supervisor. Usar el Keypad del Design System para tablet/PDA.', NULL, 'abierta', NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mvu3ar27-4bd7bb', '2026-10-29T22:03:08.287Z', 'Thomas Uriel Fernández', NULL, 'pendiente', NULL, '[Producto] Tablero de indicadores de stock', 'Quiebres de stock, rotación y días de cobertura por categoría.', NULL, 'abierta', NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mvu3jl2x-42da62', '2026-10-29T22:10:00.441Z', 'Thomas Uriel Fernández', NULL, 'decision', NULL, 'Alcance prioritario del backoffice: descuentos, armado de combos y alertas', 'Revisión del backoffice del 15/10: esos tres ejes alcanzan para justificar el sistema. Se pulen antes de sumar funcionalidades nuevas. Los pendientes [Producto] (lotes, mermas, conteo, tablero) van después.', 'backend/src/main/java/ar/com/coto/stock/service/ServicioValorizacion.java,backend/src/main/java/ar/com/coto/stock/domain/model/ComboStock.java,backend/src/main/java/ar/com/coto/stock/domain/observer/AlertaStockBajo.java', NULL, NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mvu3jl4d-004617', '2026-10-29T22:10:00.493Z', 'Thomas Uriel Fernández', NULL, 'pendiente', NULL, '[Alta] Destinatarios de avisos como listas de emails, fuera de la política de reposición', 'Hoy el modal de Compras → Reposición → Política define reposición y también un único contacto/canal por artículo. Separar: nueva sección Configuración → Destinatarios de avisos con listas de emails por categoría y una lista general; el modal de política queda solo con parámetros de reposición; AlertaStockBajo envía un mail por cada dirección. Evaluar dejar SMS/WhatsApp en segundo plano. Requiere migración db/upgrade-*.sql.', 'backend/src/main/java/ar/com/coto/stock/domain/reposicion/PoliticaReposicion.java,backend/src/main/java/ar/com/coto/stock/service/ServicioContactos.java,frontend/src/pages/Purchases.tsx,frontend/src/pages/Settings.tsx', 'abierta', NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mvu3jl5s-83a1df', '2026-10-29T22:10:00.545Z', 'Thomas Uriel Fernández', NULL, 'pendiente', NULL, '[Alta] Armado y desarmado de combos con stock propio', 'Los combos hoy son virtuales (disponible calculado desde componentes, sin contadores). Mantener ese modelo (Composite) y agregar movimientos ARMADO/DESARMADO que pasan N unidades de los componentes al stock propio del combo y viceversa, para combos armados físicamente (ej. canastas). Definir cómo conviven stock propio y disponible virtual, y qué pasa con componentes compartidos.', 'backend/src/main/java/ar/com/coto/stock/domain/model/ComboStock.java,backend/src/main/java/ar/com/coto/stock/domain/model/TipoMovimiento.java,backend/src/main/resources/schema.sql', 'abierta', NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mvu3jl76-6cab97', '2026-10-29T22:10:00.594Z', 'Thomas Uriel Fernández', NULL, 'pendiente', NULL, '[Alta] Documento funcional de los tres ejes: descuentos, combos y alertas', 'Explicar cada eje con su caso de uso, el patrón que lo resuelve (Decorator en ServicioValorizacion, Composite en ComboStock/LineaCombo, Observer + Strategy en AlertaStockBajo y notificadores), las decisiones tomadas y los límites. Incluir cómo se maneja el stock de combos y responder: componentes compartidos entre combos y venta del artículo suelto que deja sin stock al combo.', 'docs/', 'abierta', NULL);
INSERT OR REPLACE INTO memoria (id, fecha, autor, agente, tipo, pedido, titulo, detalle, archivos, estado, reemplaza) VALUES ('mvu3mvmx-75b422', '2026-10-29T22:12:34.090Z', 'Thomas Uriel Fernández', NULL, 'evento', NULL, 'Rama feature/backoffice-harness-design-system subida al repo', 'Commits: backend del backoffice, frontend + Design System, harness + memoria, documentación como producto COTO. Pendiente: PR a main.', NULL, NULL, NULL);
